insert into core.violations (non_compliance_id, activity_id, section_id, operation_id, activity_date, standard_code, standard_title, risk_level, narrative, corrected_at_inspection, corrected_date, verified_date, technical_assistance, via_investigation) values (1022644083, 904054124, 1939588297, 1366137, '2024-01-10', '746.1205(a)(4)', 'Supervision ensures each child?s safety, well-being, including physical proximity and auditory or visual awareness of each child?s on going activity', 'High', 'Based on information obtained during a DFPS investigation, it was determined a child in care was not supervised at a heightened level that ensured their continued safety. The child had attempted to leave their classroom several times before being sent to the office. Under the supervision of the office staff, the child left the operation through the front door and was discovered in the parking lot. The office staff did not see the child leave the building.', false, '2024-02-14', '2024-02-26', true, true) on conflict do nothing;
insert into core.violations (non_compliance_id, activity_id, section_id, operation_id, activity_date, standard_code, standard_title, risk_level, narrative, corrected_at_inspection, corrected_date, verified_date, technical_assistance, via_investigation) values (1022319220, 903958766, 1939183860, 1366137, '2024-03-20', null, 'HRC 42.04271 - Parent''s Rights', 'Medium', 'Ten children records were reviewed. The admission records did not have an acknowledgement that the parent had received a copy of the Parent''s Rights form.', false, '2024-03-25', '2024-03-22', true, false) on conflict do nothing;
