insert into core.violations (non_compliance_id, activity_id, section_id, operation_id, activity_date, standard_code, standard_title, risk_level, narrative, corrected_at_inspection, corrected_date, verified_date, technical_assistance, via_investigation) values (1022644077, 904054122, 1939588295, 1366137, '2022-10-13', '746.3501(1)', 'Diaper Changing Steps- Prompt', 'Medium High', 'This standard was tasked over for the investigation and was found to be deficient. Through interviews with staff, it was determined that on 9/26/2022, a child''s pull up diaper was not promptly changed.', false, '2022-11-04', '2022-11-04', true, true) on conflict do nothing;
insert into core.violations (non_compliance_id, activity_id, section_id, operation_id, activity_date, standard_code, standard_title, risk_level, narrative, corrected_at_inspection, corrected_date, verified_date, technical_assistance, via_investigation) values (1022644089, 904054127, 1939588300, 1366137, '2024-07-19', '746.4971(2)', 'Inflatables - Open Used According to Manufacturer''s Instructions', 'Medium High', 'This standard was tasked over for this investigation and found to be deficient. During the course of the investigation, it was determined that the operation did not obtain any manufacturer guidelines and/or instructions during the rental of the water slide. Without the instructions posted on the slide or given, certain safety protocols could not have been followed.', false, '2024-08-16', '2024-08-07', true, true) on conflict do nothing;
