insert into core.violations (non_compliance_id, activity_id, section_id, operation_id, activity_date, standard_code, standard_title, risk_level, narrative, corrected_at_inspection, corrected_date, verified_date, technical_assistance, via_investigation) values (1022666873, 904065736, 1939599810, 1475158, '2025-09-11', '746.1205(a)(4)', 'Supervision ensures each child?s safety, well-being, including physical proximity and auditory or visual awareness of each child?s on going activity', 'High', 'This standard was tasked over for this investigation and found to be deficient. A child was left unsupervised on the infants playground after their class had gone inside. The child was not accounted for and was standing in the playground area alone after the caregiver and classmates had already gone back inside.  ----------------  The caregiver involved in the incident is no longer employed at the facility. Additional supervision training has been completed with all staff present. Also, proper name to face procedures were conducted and observed during the inspection time.', true, '2025-09-15', null, true, true) on conflict do nothing;
insert into core.violations (non_compliance_id, activity_id, section_id, operation_id, activity_date, standard_code, standard_title, risk_level, narrative, corrected_at_inspection, corrected_date, verified_date, technical_assistance, via_investigation) values (1022630418, 904065738, 1939599812, 1475158, '2026-06-01', '746.1205(a)(4)', 'Supervision ensures each child?s safety, well-being, including physical proximity and auditory or visual awareness of each child?s on going activity', 'High', 'A caregiver left a child unsupervised outside of the classroom in fenced area.', false, '2026-06-29', '2026-07-08', true, true) on conflict do nothing;
