insert into core.violations (non_compliance_id, activity_id, section_id, operation_id, activity_date, standard_code, standard_title, risk_level, narrative, corrected_at_inspection, corrected_date, verified_date, technical_assistance, via_investigation) values (1022673384, 904065736, 1939599810, 1475158, '2025-09-11', '746.2805(3)', 'Prohibited Punishments - Grabbing and Pulling', 'High', 'This standard was tasked over for this investigation and found to be deficient. It was determined that caregivers did observe another grab and pull on a child in care while present. During the inspection time it was determined that the named caregiver of these allegations is no longer present at the facility. No forms of prohibited punishment were observed during the inspection.', true, '2025-09-15', null, true, true) on conflict do nothing;
insert into core.violations (non_compliance_id, activity_id, section_id, operation_id, activity_date, standard_code, standard_title, risk_level, narrative, corrected_at_inspection, corrected_date, verified_date, technical_assistance, via_investigation) values (1022301190, 903994162, 1939406379, 1475158, '2025-06-05', '746.5307(b)', 'Fire Extinguishers Serviced', 'Medium High', 'The fire extinguishers were serviced last in February of 2024. The fire extinguishers have not been serviced just yet for this year.', false, '2025-06-19', '2025-06-20', true, false) on conflict do nothing;
insert into core.violations (non_compliance_id, activity_id, section_id, operation_id, activity_date, standard_code, standard_title, risk_level, narrative, corrected_at_inspection, corrected_date, verified_date, technical_assistance, via_investigation) values (1022630414, 904065734, 1939599808, 1475158, '2025-06-06', '746.1205(a)(4)', 'Supervision ensures each child?s safety, well-being, including physical proximity and auditory or visual awareness of each child?s on going activity', 'High', 'This standard was tasked over for this investigation and found to be deficient. A child was left unsupervised on the preschool playground at the operation for approximately 3 minutes after their class had gone back inside. The child was under the play structure when the class went inside.  -------------------  The caregiver involved in the incident was observed properly supervising and engaging with the children during the inspection time. Additional supervision training had to be completed by the caregiver before they could return back to the classroom. Also, a second caregiver/helper has been made available to assist the caregiver and class during transition times to and from the classroom.', true, '2025-06-10', null, true, true) on conflict do nothing;
insert into core.violations (non_compliance_id, activity_id, section_id, operation_id, activity_date, standard_code, standard_title, risk_level, narrative, corrected_at_inspection, corrected_date, verified_date, technical_assistance, via_investigation) values (1022397295, 903994161, 1939406370, 1475158, '2024-11-22', '746.1315(b)(1)', 'CPR Training and Recertification Adhere to Guidelines-skill based', 'Medium High', 'Approximately 8 caregivers did not have hands-on CPR training certifications on file for review.', false, '2024-12-13', '2024-11-27', true, false) on conflict do nothing;
insert into core.violations (non_compliance_id, activity_id, section_id, operation_id, activity_date, standard_code, standard_title, risk_level, narrative, corrected_at_inspection, corrected_date, verified_date, technical_assistance, via_investigation) values (1022679891, 904065833, 1939599907, 1476477, '2024-08-27', '746.1205(a)(4)', 'Supervision ensures each child?s safety, well-being, including physical proximity and auditory or visual awareness of each child?s on going activity', 'High', 'This rule was evaluated with regard to an investigation and a deficiency was found.  Based on the information gathered, it was determined that a child was left unsupervised for a few minutes unharmed in the classroom when the children were transitioned from the classroom to the gym.', false, '2024-09-16', '2024-08-29', true, true) on conflict do nothing;
