insert into core.violations (non_compliance_id, activity_id, section_id, operation_id, activity_date, standard_code, standard_title, risk_level, narrative, corrected_at_inspection, corrected_date, verified_date, technical_assistance, via_investigation) values (1022689169, 904068927, 1939602974, 1510758, '2025-11-13', '746.3301(f)(1)', 'Nutrition and Food Service - Drinking water available at every snack, mealtime, and during and after active play', 'Medium High', 'This standard was tasked over for this investigation and found to be deficient. It was determined during this investigation that the child mentioned in the report was not given and/or offered water or a change of milk to drink through the school day. The child was allowed to only drink the same milk he arrived to care with throughout the day. the center director, has in place that the children''s personal cups can only be filled with water at drop off time. Milk will be given throughout the day in disposal cups.', true, '2025-12-25', null, true, true) on conflict do nothing;
